    tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid
  );

GRANT SELECT, INSERT, UPDATE, DELETE ON app.documents TO app_runtime;
REVOKE TRUNCATE, REFERENCES, TRIGGER ON app.documents FROM app_runtime;
```

