validateKeyRing(ring);

const token = generateToken();
const cookie = signCookie(token, ring);

assert.equal(verifyCookie(cookie, ring)?.token, token);
assert.equal(hashSessionToken(token).length, 32);

const parts = cookie.split(".");
parts = generateToken();
assert.equal(verifyCookie(parts.join("."), ring), null);

assert.equal(verifyCookie(cookie + "=", ring), null);
assert.equal(verifyCookie(cookie.replace(".new.", ".unknown."), ring), null);
assert.equal(verifyCookie("invalid", ring), null);
